def merge_dicts(a, b):
    """
    Deeply merges dict b into dict a without mutating either input.
    Returns a new dict.
    """
    result = {}
    # Add all items from a
    for key, value in a.items():
        result[key] = value

    # Merge items from b
    for key, value in b.items():
        if key in result:
            # If both a and b have the key, check if both values are dicts
            if isinstance(result[key], dict) and isinstance(value, dict):
                # Recursively merge the nested dicts
                result[key] = merge_dicts(result[key], value)
            else:
                # Overwrite with value from b
                result[key] = value
        else:
            # Add new key from b
            result[key] = value

    return result
```

