import urllib.parse

def parse_query(qs):
    """
    Parses a URL query string into a dictionary.
    Repeated keys are stored in a list.
    Percent-encoding and '+' as space are decoded.
    """
    if not qs:
        return {}

    # urllib.parse.parse_qs returns a dictionary where values are lists
    # It automatically decodes percent-encoding and '+' to space
    parsed = urllib.parse.parse_qs(qs, keep_blank_values=True)

    # Convert the lists to single values if there is only one item
    # This matches the behavior of a standard dict where keys are unique
    result = {}
    for key, values in parsed.items():
        if len(values) == 1:
            result[key] = values[0]
        else:
            result[key] = values

    return result
```

