def human_bytes(n):
    """
    Format a byte count using binary units (B, KiB, MiB, GiB, TiB).
    """
    for unit in ['B', 'KiB', 'MiB', 'GiB', 'TiB']:
        if n < 1024.0:
            if unit == 'B':
                return f"{n:.0f} {unit}"
            else:
                return f"{n:.1f} {unit}"
        n /= 1024.0
    return f"{n:.1f} PiB"
