def parse_duration(s):
    """
    Parses a duration string (e.g., '1h30m', '45s', '2d') into total seconds.
    Raises ValueError if the string is unparseable.
    """
    if not s:
        raise ValueError("Empty string")

    total_seconds = 0
    i = 0
    n = len(s)

    while i < n:
        # Extract the number part
        num_str = ''
        while i < n and s[i].isdigit():
            num_str += s[i]
            i += 1

        # If no number was found, the string is invalid
        if not num_str:
            raise ValueError(f"Invalid duration format: {s}")

        # Extract the unit part
        if i < n:
            unit = s[i]
            i += 1
        else:
            # If the string ends with a number but no unit, it's invalid
            raise ValueError(f"Invalid duration format: {s}")

        # Convert to integer
        try:
            value = int(num_str)
        except ValueError:
            raise ValueError(f"Invalid duration format: {s}")

        # Add to total based on unit
        if unit == 's':
            total_seconds += value
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 'h':
            total_seconds += value * 3600
        elif unit == 'd':
            total_seconds += value * 86400
        else:
            raise ValueError(f"Unknown unit: {unit}")

    return total_seconds
```

