import heapq

def topk(items, k):
    if k <= 0:
        return []
    if k >= len(items):
        return sorted(items, reverse=True)

    # Use a min-heap to keep track of the k largest items
    # The heap will store tuples of (-value, item) to simulate a max-heap behavior
    # for the heapq.nlargest function, or we can use heapq.nsmallest on negatives.
