function rotateArray(arr, k) {
  if (!Array.isArray(arr) || arr.length === 0) {
    return [];
  }

  const n = arr.length;
  k = k % n;

  if (k < 0) {
    k = k + n;
  }

  if (k === 0) {
    return [...arr];
  }

  const rotated = new Array(n);
