export function maxBy<T>(arr: T[], f: (t: T) => number): T | undefined {
  if (arr.length === 0) {
    return undefined;
  }

  let maxItem: T = arr[0];
  let maxVal: number = f(arr[0]);

  for (let i = 1; i < arr.length; i++) {
    const currentVal = f(arr[i]);
    if (currentVal > maxVal) {
      maxVal = currentVal;
      maxItem = arr[i];
