import React, { useState, useEffect, useCallback } from 'react';
import { FlatList, ActivityIndicator, View, Text, StyleSheet } from 'react-native';

const InfiniteScrollList = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);

  // Simulate fetching data
  const fetchData = async (pageNum) => {
    setLoading(true);
    try {
      // Simulate network delay
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Simulate generating new data
      const newData = Array.from({ length: 10 }, (_, i) => ({
        id: `${pageNum}-${i}`,
        title: `Item ${pageNum}-${i}`,
      }));

      setData(prevData => [...prevData, ...newData]);
      setPage(prevPage => prevPage + 1);

      // Simulate end of data after 3 pages
      if (pageNum >= 3) {
        setHasMore(false);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  // Initial load
  useEffect(() => {
    fetchData(1);
  }, []);

  // Handle infinite scroll
  const handleLoadMore = useCallback(() => {
    if (loading || !hasMore) return;
    fetchData(page);
  }, [loading, hasMore, page]);

  const renderItem = ({ item }) => (
    <View style={styles.item}>
      <Text style={styles.text}>{item.title}</Text>
    </View>
  );

  return (
    <FlatList
      data={data}
      renderItem={renderItem}
      keyExtractor={item => item.id}
      onEndReached={handleLoadMore}
      onEndReachedThreshold={0.5}
      ListFooterComponent={
        loading ? (
          <View style={styles.footer}>
            <ActivityIndicator size="small" color="#0000ff" />
          </View>
        ) : null
      }
      // Remove extra scroll behavior to prevent double loading
      bounces={false}
    />
  );
};

const styles = StyleSheet.create({
  item: {
    padding: 20,
    borderBottomWidth: 1,
    borderBottomColor: '#ccc',
  },
  text: {
    fontSize: 16,
  },
  footer: {
    padding: 20,
    alignItems: 'center',
  },
});

export default InfiniteScrollList;
```

