import React, { useEffect, useState } from 'react';
import { View, Text, Button, Linking, Alert } from 'react-native';

const OpenExternalUrl = () => {
  const [canOpen, setCanOpen] = useState(false);
  const [loading, setLoading] = useState(true);

  const checkUrl = async () => {
    const supported = await Linking.canOpenURL('https://www.google.com');
    setCanOpen(supported);
    setLoading(false);
  };

  useEffect(() => {
    checkUrl();
  }, []);

  const handlePress = async () => {
    const supported = await Linking.canOpenURL('https://www.google.com');
    if (supported) {
      await Linking.openURL('https://www.google.com');
    } else {
      Alert.alert('Error', "Don't know how to open this URL: " + 'https://www.google.com');
    }
  };

  if (loading) {
    return <View><Text>Loading...</Text></View>;
  }

  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <Text>Can Open URL: {canOpen ? 'Yes' : 'No'}</Text>
      <Button
        title={canOpen ? "Open URL" : "Cannot Open"}
        onPress={handlePress}
        disabled={!canOpen}
      />
    </View>
  );
};

export default OpenExternalUrl;
